def small_world_graph(n: int, k: int, p: float, rng: random.Random):
    k = max(2, (k // 2) * 2)
    adj = [set() for _ in range(n)]
    # ring lattice
    for i in range(n):
        for j in range(1, k // 2 + 1):
            u, v = i, (i + j) % n
            adj[u].add(v)
            adj[v].add(u)
    # rewiring
    for i in range(n):
        for v in list(adj[i]):
            if i < v and rng.random() < p:
                adj[i].remove(v)
                adj[v].remove(i)
                candidates = [x for x in range(n) if x != i and x not in adj[i]]
                if candidates:
                    w = rng.choice(candidates)
                    adj[i].add(w)
                    adj[w].add(i)
    return [list(s) for s in adj]

